pm.test('incident is classified and carries allowed_transitions', () => {
  const body = pm.response.json();
  pm.expect(body).to.have.property('id');
  pm.expect(body.status).to.eql('validating');
  pm.expect(body.incident_type).to.be.a('string');
  pm.expect(body.allowed_transitions).to.be.an('array');
  pm.expect(body.sla).to.have.property('due_at');
  pm.collectionVariables.set('incidentId', body.id);
});

